#!/usr/bin/env python3
"""
Civ6 District Adjacency Bonus Optimizer - Optimized version
Scenario 3: population 9, 1 city, GENERIC civ, GS ruleset
"""

import sqlite3
import json
import itertools
from collections import defaultdict

WIDTH = 44
HEIGHT = 26

def plot_id_to_xy(pid):
    return (pid % WIDTH, pid // WIDTH)

def get_hex_neighbors(x, y):
    if y % 2 == 0:
        offsets = [(1, 0), (-1, 0), (0, 1), (0, -1), (-1, 1), (-1, -1)]
    else:
        offsets = [(1, 0), (-1, 0), (0, 1), (0, -1), (1, 1), (1, -1)]
    result = []
    for dx, dy in offsets:
        nx, ny = x + dx, y + dy
        if 0 <= nx < WIDTH and 0 <= ny < HEIGHT:
            result.append((nx, ny))
    return result

# Load map
conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
c = conn.cursor()

plots = {}
c.execute("SELECT ID, TerrainType, IsImpassable FROM Plots")
for pid, terrain, imp in c.fetchall():
    xy = plot_id_to_xy(pid)
    plots[xy] = {'terrain': terrain, 'impassable': bool(imp), 'feature': None, 'has_river': False}

c.execute("SELECT ID, FeatureType FROM PlotFeatures")
for pid, feat in c.fetchall():
    xy = plot_id_to_xy(pid)
    if xy in plots:
        plots[xy]['feature'] = feat

c.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers")
river_data = {}
for pid, ne, w, nw in c.fetchall():
    xy = plot_id_to_xy(pid)
    river_data[xy] = (bool(ne), bool(w), bool(nw))
conn.close()

# Mark river tiles
for (x, y), (ne, w, nw) in river_data.items():
    if ne or w or nw:
        plots[(x,y)]['has_river'] = True
    if ne:
        if y % 2 == 0: nb = (x, y+1)
        else: nb = (x+1, y+1)
        if nb in plots: plots[nb]['has_river'] = True
    if w:
        nb = (x-1, y)
        if nb in plots: plots[nb]['has_river'] = True
    if nw:
        if y % 2 == 0: nb = (x-1, y+1)
        else: nb = (x, y+1)
        if nb in plots: plots[nb]['has_river'] = True

# Helper checks
def is_land(p): return p in plots and plots[p]['terrain'] not in ('TERRAIN_OCEAN', 'TERRAIN_COAST')
def is_mountain(p): return p in plots and 'MOUNTAIN' in plots[p]['terrain']
def is_flat(p): return is_land(p) and not plots[p]['impassable']
def is_jungle(p): return p in plots and plots[p]['feature'] == 'FEATURE_JUNGLE'
def is_forest(p): return p in plots and plots[p]['feature'] == 'FEATURE_FOREST'
def is_geothermal(p): return p in plots and plots[p]['feature'] == 'FEATURE_GEOTHERMAL_FISSURE'
def is_floodplains(p): return p in plots and plots[p].get('feature','') and 'FLOODPLAINS' in (plots[p]['feature'] or '')
def has_river(p): return p in plots and plots[p]['has_river']

# Build neighbor cache
neighbor_cache = {}
for p in plots:
    neighbor_cache[p] = get_hex_neighbors(p[0], p[1])

# Precompute flat land tiles
flat_tiles = sorted([p for p in plots if is_flat(p)])
print(f"Flat tiles: {len(flat_tiles)}")

# Precompute natural adjacency scores for each tile for each district type
# This is the component of adjacency from terrain/features (independent of other placements)

def campus_natural(pos):
    bonus = 0
    for n in neighbor_cache.get(pos, []):
        if is_mountain(n): bonus += 1
        if is_geothermal(n): bonus += 1
    # Jungles counted separately since districts placed there remove them
    return bonus

def campus_jungle_count(pos, occupied):
    """Count jungles adjacent to pos not occupied by districts"""
    count = 0
    for n in neighbor_cache.get(pos, []):
        if is_jungle(n) and n not in occupied:
            count += 1
    return count

def holy_site_natural(pos):
    bonus = 0
    for n in neighbor_cache.get(pos, []):
        if is_mountain(n): bonus += 1
    return bonus

def holy_site_forest_count(pos, occupied):
    count = 0
    for n in neighbor_cache.get(pos, []):
        if is_forest(n) and n not in occupied:
            count += 1
    return count

# Population 9: floor((pop-1)/3) + 1 = floor(8/3) + 1 = 3 specialty district slots
# Non-slot: Aqueduct, Dam, Government Plaza

# Strategy: try the most promising district combinations
# Best adjacency sources:
# - Campus near mountains/geothermal: up to 3+ base
# - Commercial Hub on river: +2 base, +1 per 2 adj districts
# - Industrial Zone with Dam + Aqueduct: +2+2 + district adjacency
# - Holy Site near mountains: +1 per mountain
# - Theater Square: only district adjacency

# Best 3-specialty combos to try:
# 1. Campus + Industrial Zone + Commercial Hub (+ Dam + Aqueduct + Gov Plaza)
# 2. Campus + Industrial Zone + Holy Site (+ Dam + Aqueduct)
# 3. Campus + Commercial Hub + Holy Site

# Let me focus on smart combinations
print("\n=== Analyzing best positions ===")

# Campus best positions (pre-score by natural features):
print("Campus scores:")
for t in flat_tiles:
    s = campus_natural(t)
    jc = campus_jungle_count(t, set())
    total = s + jc // 2
    if total > 0:
        print(f"  {t}: mountains+geothermal={s}, jungles={jc}, est_bonus={total}")

print("\nHoly Site scores:")
for t in flat_tiles:
    s = holy_site_natural(t)
    fc = holy_site_forest_count(t, set())
    total = s + fc // 2
    if total > 0:
        print(f"  {t}: mountains={s}, forests={fc}, est_bonus={total}")

print("\nCommercial Hub (river tiles):")
for t in flat_tiles:
    if has_river(t):
        adj_flat = sum(1 for n in neighbor_cache[t] if is_flat(n))
        print(f"  {t}: river=+2, adj_flat_count={adj_flat}")

print("\nDam candidates (floodplains + river):")
for t in flat_tiles:
    if is_floodplains(t) and has_river(t):
        print(f"  {t}")

print("\nAqueduct candidates (adj to mountain or river, will need adj to CC):")

# Now let's do a targeted search
# For each city center, identify the best district setup

def get_range3(center):
    result = {center}
    frontier = {center}
    for _ in range(3):
        nf = set()
        for p in frontier:
            for n in neighbor_cache.get(p, []):
                if n not in result and n in plots:
                    result.add(n)
                    nf.add(n)
        frontier = nf
    return result

def can_place_aqueduct(pos, cc):
    """Must be adjacent to CC AND adjacent to mountain or river or oasis"""
    nbs = neighbor_cache.get(pos, [])
    if cc not in nbs:
        return False
    # Need water source: adjacent mountain, or the aqueduct tile itself has river, or adjacent oasis
    for n in nbs:
        if is_mountain(n):
            return True
    if has_river(pos):
        return True
    return False

def can_place_dam(pos, cc):
    return is_floodplains(pos) and has_river(pos)

def calc_adjacency(placement, cc):
    """Calculate total adjacency for a placement dict {district_name: pos}"""
    occupied = set(placement.values()) | {cc}
    total = 0
    bonuses = {}

    for dname, dpos in placement.items():
        bonus = 0
        nbs = neighbor_cache.get(dpos, [])

        if dname == 'CAMPUS':
            for n in nbs:
                if is_mountain(n): bonus += 1
                if is_geothermal(n): bonus += 1
            jungles = sum(1 for n in nbs if is_jungle(n) and n not in occupied)
            bonus += jungles // 2

        elif dname == 'HOLY_SITE':
            for n in nbs:
                if is_mountain(n): bonus += 1
            forests = sum(1 for n in nbs if is_forest(n) and n not in occupied)
            bonus += forests // 2

        elif dname == 'COMMERCIAL_HUB':
            if has_river(dpos): bonus += 2
            dist_count = 0
            for n in nbs:
                if n == cc:
                    dist_count += 1
                elif n in placement.values():
                    dist_count += 1
            bonus += dist_count // 2

        elif dname == 'INDUSTRIAL_ZONE':
            dist_count = 0
            for n in nbs:
                if n == cc:
                    dist_count += 1
                elif n in placement.values():
                    # Check what's there
                    for dn, dp in placement.items():
                        if dp == n:
                            if dn in ('AQUEDUCT', 'DAM', 'CANAL'):
                                bonus += 2
                            dist_count += 1
                            break
            bonus += dist_count // 2

        elif dname == 'THEATER_SQUARE':
            dist_count = 0
            for n in nbs:
                if n == cc:
                    dist_count += 1
                elif n in placement.values():
                    for dn, dp in placement.items():
                        if dp == n:
                            if dn in ('ENTERTAINMENT_COMPLEX', 'WATER_PARK'):
                                bonus += 1
                            dist_count += 1
                            break
            bonus += dist_count // 2

        elif dname == 'ENCAMPMENT':
            dist_count = 0
            for n in nbs:
                if n == cc:
                    dist_count += 1
                elif n in placement.values():
                    dist_count += 1
            bonus += dist_count // 2

        # AQUEDUCT, DAM, GOVERNMENT_PLAZA: 0 own adjacency

        bonuses[dname] = bonus
        total += bonus

    return total, bonuses

best_total = 0
best_result = None
count = 0

# Focus on promising city center locations:
# The land area is roughly x=20-27, y=11-17
# City center should be central to maximize reachable tiles

for cc in flat_tiles:
    workable = get_range3(cc)
    placeable = [t for t in workable if is_flat(t) and t != cc]

    if len(placeable) < 3:
        continue

    # Strategy 1: Campus + IZ + Commercial Hub + Dam + Aqueduct + Gov Plaza
    # Strategy 2: Campus + IZ + Commercial Hub + Dam + Aqueduct
    # Strategy 3: Campus + IZ + Commercial Hub + Dam
    # Strategy 4: Campus + IZ + Commercial Hub + Aqueduct
    # Strategy 5: Campus + IZ + Commercial Hub
    # Strategy 6: Campus + IZ + Holy Site + Dam + Aqueduct
    # And variations...

    # Try different specialty combos
    specialty_combos = [
        ['CAMPUS', 'INDUSTRIAL_ZONE', 'COMMERCIAL_HUB'],
        ['CAMPUS', 'INDUSTRIAL_ZONE', 'HOLY_SITE'],
        ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE'],
        ['CAMPUS', 'COMMERCIAL_HUB', 'THEATER_SQUARE'],
        ['CAMPUS', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
        ['INDUSTRIAL_ZONE', 'COMMERCIAL_HUB', 'HOLY_SITE'],
        ['INDUSTRIAL_ZONE', 'COMMERCIAL_HUB', 'THEATER_SQUARE'],
    ]

    dam_pos = [t for t in placeable if can_place_dam(t, cc)]
    aqueduct_pos = [t for t in placeable if can_place_aqueduct(t, cc)]

    for spec in specialty_combos:
        has_iz = 'INDUSTRIAL_ZONE' in spec

        # Non-slot combinations to try
        non_slot_lists = [[]]
        if has_iz:
            if dam_pos:
                non_slot_lists.append(['DAM'])
            if aqueduct_pos:
                non_slot_lists.append(['AQUEDUCT'])
            if dam_pos and aqueduct_pos:
                non_slot_lists.append(['DAM', 'AQUEDUCT'])
        # Add Government Plaza variants
        gp_variants = [ns + ['GOVERNMENT_PLAZA'] for ns in non_slot_lists]
        non_slot_lists.extend(gp_variants)

        for ns in non_slot_lists:
            all_districts = spec + ns
            n_districts = len(all_districts)

            # For each district, get candidate positions
            candidates = {}
            for d in all_districts:
                cands = []
                for t in placeable:
                    if d == 'DAM' and not can_place_dam(t, cc):
                        continue
                    if d == 'AQUEDUCT' and not can_place_aqueduct(t, cc):
                        continue
                    if d == 'ENCAMPMENT':
                        if cc in neighbor_cache.get(t, []):
                            continue
                    cands.append(t)
                candidates[d] = cands

            if any(len(v) == 0 for v in candidates.values()):
                continue

            # Limit candidates
            MAX_C = 8
            for d in all_districts:
                if len(candidates[d]) > MAX_C:
                    # Pre-score
                    scored = []
                    for t in candidates[d]:
                        s = 0
                        nbs = neighbor_cache.get(t, [])
                        if d == 'CAMPUS':
                            for n in nbs:
                                if is_mountain(n): s += 1
                                if is_geothermal(n): s += 1
                                if is_jungle(n): s += 0.5
                        elif d == 'COMMERCIAL_HUB':
                            if has_river(t): s += 2
                            s += sum(0.3 for n in nbs if is_flat(n))
                        elif d == 'INDUSTRIAL_ZONE':
                            s += sum(0.5 for n in nbs if is_flat(n))
                        elif d == 'HOLY_SITE':
                            for n in nbs:
                                if is_mountain(n): s += 1
                                if is_forest(n): s += 0.5
                        elif d == 'THEATER_SQUARE':
                            s += sum(0.3 for n in nbs if is_flat(n))
                        elif d == 'GOVERNMENT_PLAZA':
                            s += sum(0.3 for n in nbs if is_flat(n))
                        scored.append((s, t))
                    scored.sort(reverse=True)
                    candidates[d] = [t for _, t in scored[:MAX_C]]

            # Recursive assignment
            def assign(idx, used, pl):
                global best_total, best_result, count

                if idx == n_districts:
                    count += 1
                    t, b = calc_adjacency(pl, cc)
                    if t > best_total:
                        best_total = t
                        best_result = {'cc': cc, 'placement': dict(pl), 'bonuses': dict(b)}
                    return

                d = all_districts[idx]
                for t in candidates[d]:
                    if t in used:
                        continue
                    pl[d] = t
                    used.add(t)
                    assign(idx + 1, used, pl)
                    used.discard(t)
                    del pl[d]

            assign(0, set(), {})

print(f"\nTotal combinations tested: {count}")
print(f"\n=== BEST SOLUTION ===")
if best_result:
    print(f"City center: {best_result['cc']}")
    print(f"Total adjacency: {best_total}")
    print(f"Placements: {best_result['placement']}")
    print(f"Bonuses: {best_result['bonuses']}")

    import os
    os.makedirs('/output', exist_ok=True)

    output = {
        "city_center": list(best_result['cc']),
        "placements": {k: list(v) for k, v in best_result['placement'].items()},
        "adjacency_bonuses": best_result['bonuses'],
        "total_adjacency": best_total
    }

    with open('/output/scenario_3.json', 'w') as f:
        json.dump(output, f, indent=2)

    print(f"\nSolution written to /output/scenario_3.json")
    print(json.dumps(output, indent=2))

