        ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE'],
        ['CAMPUS', 'COMMERCIAL_HUB', 'THEATER_SQUARE'],
        ['CAMPUS', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
        ['INDUSTRIAL_ZONE', 'COMMERCIAL_HUB', 'HOLY_SITE'],
        ['INDUSTRIAL_ZONE', 'COMMERCIAL_HUB', 'THEATER_SQUARE'],
    ]

    dam_pos = [t for t in placeable if can_place_dam(t, cc)]
    aqueduct_pos = [t for t in placeable if can_place_aqueduct(t, cc)]

    for spec in specialty_combos:
