                                if is_geothermal(n): s += 1
                                if is_jungle(n): s += 0.5
                        elif d == 'COMMERCIAL_HUB':
                            if has_river(t): s += 2
                            s += sum(0.3 for n in nbs if is_flat(n))
                        elif d == 'INDUSTRIAL_ZONE':
                            s += sum(0.5 for n in nbs if is_flat(n))
                        elif d == 'HOLY_SITE':
                            for n in nbs:
                                if is_mountain(n): s += 1
                                if is_forest(n): s += 0.5
                        elif d == 'THEATER_SQUARE':
                            s += sum(0.3 for n in nbs if is_flat(n))
                        elif d == 'GOVERNMENT_PLAZA':
                            s += sum(0.3 for n in nbs if is_flat(n))
                        elif d == 'ENCAMPMENT':
                            s += sum(0.3 for n in nbs if is_flat(n))
                        scored.append((s, t))
                    scored.sort(reverse=True)
                    candidates[d] = [t for _, t in scored[:MAX_C]]

            def assign(idx, used, pl):
                if idx == n_districts:
                    t, b = calc_adjacency(pl, cc)
                    if t > best['total']:
                        best['total'] = t
                        best['result'] = {'cc': cc, 'placement': dict(pl), 'bonuses': dict(b)}
                    return

                d = all_districts[idx]
                for t in candidates[d]:
                    if t in used:
                        continue
                    pl[d] = t
                    used.add(t)
                    assign(idx + 1, used, pl)
                    used.discard(t)
                    del pl[d]

            assign(0, set(), {})

print(f"Total combinations: {count}")
print(f"\n=== BEST SOLUTION ===")
if best_result:
    print(f"City center: {best_result['cc']}")
    print(f"Total adjacency: {best_total}")
    print(f"Placements: {best_result['placement']}")
    print(f"Bonuses: {best_result['bonuses']}")

    import os
    os.makedirs('/output', exist_ok=True)

    output = {
        "city_center": list(best_result['cc']),
        "placements": {k: list(v) for k, v in best_result['placement'].items()},
        "adjacency_bonuses": best_result['bonuses'],
        "total_adjacency": best_total
    }

    with open('/output/scenario_3.json', 'w') as f:
        json.dump(output, f, indent=2)

    print(json.dumps(output, indent=2))

